base.expression:
// halve scaling from magic crit, since theres no avoidance contesting healing crits
const base = 1.0 + (GetStat(GetOwner(), $#10516612381411111:109343399171811$)-1.0) / 2.0;
const baseRating = (GetStat(GetInstigator(), $#10516612381411111:6064628617694412803$)+GetStat(GetInstigator(), $#10516612381411111:109342909421182$))/2.0;
const coeff = EvalE($#10516612381411112:6064630400897515547$);
const coeffMult = EvalE($#10516612381411112:6064633883748794468$);
const baseAdj = base - baseRating / (baseRating * coeffMult + coeff);
const rating = baseRating + GetStat(GetInstigator(), $#10516612381411111:6064629246805082117$);
baseAdj + rating / (rating * coeffMult + coeff)
